scripts.药王谷归来.txt:
	If ($Event == $2031) @L2031;//药王谷归来
	Return;
	
@L2031:
	PlayerGoto(16,207);
	SetPlayerDir(5);
	Say("杨影枫：真儿！",4);
	Say("纳兰真：影枫哥！",9);
	PlayerGoto(18,201);
	SetPlayerDir(5);
	SetNpcKind("蔷薇",1);
	NpcGoto("蔷薇",19,202);
	SetNpcDir("蔷薇",4);
	Say("杨影枫：真儿，终于又见到你了，你还好吧。",3);
	Say("纳兰真：影枫哥，我还好，我在这里等你们已经三天了。",9);
	Say("蔷薇：真儿姐姐……再见到你我真高兴。",29);
	Say("杨影枫：薇儿她……",5);
	Say("纳兰真：影枫哥，我都知道。",9);
	SetNpcDir("纳兰真",0);
	Say("纳兰真：蔷薇妹妹，我已经给你拿到“穿肠雪蛛”得解药了！",9);
	Say("蔷薇：（哭泣）真的！",30);
	PlaySound("蔷薇哭声1.wav");
	Say("杨影枫：真儿……你是怎么拿到的。",4);
	Say("纳兰真：我假意和爹和好，然后从司空情那里骗来的",10);
	Say("杨影枫：真儿……真难为你了……",3);
	Say("纳兰真：别耽误了，我们赶快进去给蔷薇妹妹解毒吧。",9);
	Say("杨影枫：嗯……",3);
	FadeOut();
	SetNpcPos("蔷薇",56,158);
	SetNpcRes("蔷薇","npc019-蔷薇躺着.ini");
	SetNpcPos("纳兰真",55,159);
	SetNpcDir("纳兰真",6);
	SetPlayerPos(56,160);
	SetPlayerDir(4);
	FadeIn();
	Say("纳兰真给蔷薇服下了解药……");
	Say("蔷薇昏昏的睡着了……");
	Say("纳兰真：影枫哥，我们去外面吧，我有事情要跟你说。",9);
	Say("杨影枫：嗯……真儿",3);
	
	FadeOut();
	SetPlayerPos(36,89);
	SetNpcPos("纳兰真",36,90);
	Watch("纳兰真","杨影枫",0);
	FadeIn();
	
	Say("纳兰真：影枫哥，目前无忧教的势力已经越来越大，我爹想要称霸中原武林。",12);
	Say("杨影枫：我已经知道了，他还让我加入无忧教呢。",2);
	Say("纳兰真：那你答应了吗？",12);
	Say("杨影枫：没有。",2);
	Say("纳兰真：他已经血洗了落叶谷和武当山，并且把飞龙堡当作无忧教的秘密分舵。",12);
	Say("杨影枫：唉……看来中原武林是难免一场浩劫了。",2);
	Say("纳兰真：他得知你从摘星楼逃脱之后，非常恼怒，而你后来又独闯飞龙堡，救走了蔷薇，他就更生气了，认为你是他统一武林的最大障碍，非要除去你不可。",12);
	Say("杨影枫：其实我并不在意这些武林中争权夺利的事，我只要有你就满足了。",2);
	Say("纳兰真：影枫哥……我爹这样对你，你难道不恨我吗？",10);
	Say("杨影枫：你爹的所作所为只是他的错，和你又有什么关系？",2);
	Say("纳兰真：影枫哥……谢谢你能理解我。",10);
	Say("杨影枫：还记得我们两个在忘忧岛上一起渡过的日子吗？",3);
	Say("纳兰真：我怎么会忘记？那是我一生中最快乐的时光。",10);
	Say("杨影枫：不如我们回忘忧岛隐居吧，我不想再卷入武林中的恩怨了。",2);
	Say("纳兰真：太好了，我也这么想。",10);
	Say("纳兰真：但是我爹他……不会放过你的……他现在正在四处追杀你呢。",15);
	Say("杨影枫：为什么？我已经这样了，他还要赶尽杀绝。",4);
	Say("纳兰真：我爹他……可能已经“疯”了。",15);
	Say("杨影枫：难道我一定要和他拼个你死我活吗？",4);
	Say("纳兰真：影枫哥……你不是他的对手的。",15);
	Say("杨影枫：真儿……万一我要是死在你爹手上，你会怎么样？",2);
	Say("纳兰真：……我……那我也不想再活了。",15);
	Say("杨影枫：真儿……万一要是你爹死在我手上，你会不会不再理我了？",2);
	Say("纳兰真：……万一我爹死了……那也只能怪他咎由自取。",15);
	Say("杨影枫：真儿……你太好了。",2);
	Say("纳兰真：听说你救了眉儿姐姐，她现在在哪里呢？",10);
	Say("杨影枫：她和紫轩在寒波谷养伤。",2);
	Say("纳兰真：你与紫轩姑娘和好了吗？",10);
	Say("杨影枫：嗯……其实紫轩也是被卓非凡利用……",2);
	Say("纳兰真：影枫哥……你是不是也很喜欢眉儿姐姐、蔷薇姑娘还有紫轩姑娘？",10);
	Say("杨影枫：这个……我……",120);
	Say("纳兰真：喜欢就是喜欢……干嘛还吞吞吐吐的？",11);
	Say("杨影枫：……不过我最喜欢的还是你……",3);
	Say("纳兰真：真的吗？我不信，你为了救紫轩姑娘血洗摘星楼，又为救蔷薇姑娘独闯飞龙堡。",10);
	Say("杨影枫：不错……不过我最想救的其实是你……",3);
	Say("纳兰真：影枫哥……如果你真心喜欢她们，就把她们都娶了吧，我不会介意的。",10);
	Say("杨影枫：真儿……你的心真好……",3);
	FadeOut();
	Say("说着……杨影枫把纳兰真紧紧的抱进怀里……");
	Say("……良久……");
	ChangeMapColor(100, 150, 255);
	ChangeAsfColor(150, 200, 255);
	FadeIn();		
	Say("杨影枫：真儿……天色不早了……我们也该休息了。",3);
	Say("纳兰真：嗯……影枫哥……",9);
	SetNpcKind("纳兰真",3);
	PlayerGotoEx(39,96);
	Sleep(1000);
	FadeOut();
	SetPlayerDir(5);
	SetPlayerPos(43,211);
	PlayerGotoEx(47,202);
	FadeIn();
	PlayerGoto(47,203);
	Watch("纳兰真","杨影枫",0);
	Say("杨影枫：真儿……你就在这里休息吧，我去看看蔷薇再睡。",3);
	Say("纳兰真：……影枫哥……好吧……",9);
	SetNpcKind("纳兰真",1);
	PlayerGotoEx(43,211);
	Return;

scripts.寒波谷归来2.txt:
	If ($Event == $2040) @2040;//寒波谷归来（2人）
	Return;
	
@2040:
	MergeNpc("map030_4.npc");
	DelNpc("紫轩");
	DisableNpcAI();
	PlayerGoto(17,208);
	SetPlayerDir(5);
	SetNpcKind("月眉儿",1);
	NpcGoto("月眉儿",16,207);
