//	SetNpcKind("紫轩",1);
//	NpcGoto("紫轩",17,209);
//	SetNpcDir("紫轩",5);
	Say("杨影枫：真儿！我回来了",2);
	Say("纳兰真：影枫哥！眉儿姐！",9);
	Say("蔷薇：太好了，你们终于回来了。",29);
	Say("月眉儿：真儿妹妹，蔷薇姑娘，你们都好吧。",23);
	Say("蔷薇：都好……怎么没有看到紫轩姐呢？",29);
	Say("杨影枫：她想一个人留在寒波谷……我们进去说吧",2);
	Say("纳兰真：嗯……",9);
	FadeOut();
	SetPlayerPos(45,140);
	SetPlayerDir(1);
	SetNpcPos("纳兰真",44,143);
	SetNpcDir("纳兰真",3);
	SetNpcPos("月眉儿",45,142);
	SetNpcDir("月眉儿",3);
	SetNpcPos("蔷薇",43,141);
	SetNpcDir("蔷薇",7);
	SetNpcPos("紫轩",44,140);
	SetNpcDir("紫轩",7);
	FadeIn();
	Say("四个人正聊得开心……");
	StopMusic();
	MoveScreen(1,100,1);
	SetNpcPos("纳兰潜凛",36,158);
	NpcGoto("纳兰潜凛",42,145);
	PlayMusic("mc022.mp3");
	Say("纳兰潜凛：哈哈……杨影枫，你让老夫找得好辛苦啊！",41);
	SetNpcDir("纳兰真",1);
	SetNpcDir("月眉儿",1);
	SetNpcDir("蔷薇",1);
//	SetNpcDir("紫轩",1);
	Say("杨影枫：纳兰潜凛？",6);
	PlayerGoto(43,143);
	Say("月眉儿：我当是谁来了呢……原来是鼎鼎大名的魔教教主",22);
	Say("蔷薇：纳兰潜凛……是你杀了我爹……我要给我爹报仇！",32);
	Say("纳兰真：爹……",15);
	Sleep(550);
	Say("纳兰潜凛：真儿……你的眼里还有我这个爹吗？",39);
	Say("纳兰真：我……你不要再为难影枫哥了，他就要退出江湖了",15);
	Say("月眉儿：哼……恐怕他不但要杀杨影枫，就算我们也不会放过的",22);
	Say("纳兰潜凛：月眉儿……你也是我的女儿……",38);
	Say("月眉儿：……我爹很早就死了……",24);
	Say("杨影枫：纳兰潜凛！你来得正好，我本想看在真儿的面子上放你一条生路，怎奈你苦苦相逼，好吧，今天我们就在此做一个了断。",6);
	Say("纳兰潜凛：杨影枫，你好大口气，要不是真儿阻止我杀你，你早就没命了……",41);
	Say("杨影枫：闲话少说，我们今天就决一死战！",6);
	Say("纳兰潜凛：看在我两个女儿这么喜欢你的份上，我今天给你最后一次机会，你要是肯加入我教，我不但把她们都许配给你，而且让你继承我的教主之位。",41);
	Say("月眉儿：纳兰潜凛！我的事轮不到你来作主！",22);
	Say("蔷薇：影枫哥……你不要听他的……你要给我爹报仇啊！",32);
	Say("纳兰真：……爹……",14);

	Choose("是否要加入无忧教？","是","否",$wangwei);
	If ($wangwei == 1) @no; //不加入
	
	Say("杨影枫：（这样的条件的确很诱人）让我考虑一下……",3);
	Say("纳兰潜凛：好……你终于想通了……哈哈……",41);
	
	Say("蔷薇：影枫哥……不要啊！你如果要加入无忧教，不如就先杀了我吧！",32);
	Say("月眉儿：杨影枫！没想到你原来是这样的人……我真是瞎了眼。",24);
	Say("纳兰真：影枫哥……你怎么会……",14);
	Say("杨影枫：（看来江山和美人还是无法兼得）大家别误会，我只是想缓和一下气氛",3);

@no:
	Say("杨影枫：纳兰潜凛，你不用再费心机了，我是不会答应你的。",6);
	Say("纳兰潜凛：好……很好……既然如此，可就别管我翻脸无情了！",39);
	Say("杨影枫：这里地方太小，我们到比武场一决高下吧。",6);
	Say("纳兰潜凛：哼……就老夫领教一下……看你到底有什么高招。",39);

	FadeOut();
	SetPlayerPos(20,25);
	SetPlayerDir(5);
	SetNpcPos("纳兰真",21,24);
	SetNpcPos("月眉儿",21,25);
	SetNpcPos("蔷薇",22,26);
//	SetNpcPos("紫轩",22,27);
	SetNpcPos("纳兰潜凛",9,50);
	FadeIn();

	Say("杨影枫：真儿……想不到我与你爹的这一战还是在所难免……",7);
	Say("纳兰真：影枫哥……你尽力吧……我不会怪你的……",14);
	PlayerGoto(21,26);
	SetPlayerDir(5);
	Say("杨影枫：眉儿……如果我不小心杀了你爹……你不会……",7);
	Say("月眉儿：你最好杀了他，我就当没这个爹。",22);
	PlayerGoto(21,27);
	SetPlayerDir(5);
	Say("杨影枫：薇儿……如果我死了……你千万要活下去",7);
	Say("蔷薇：影枫哥……你不会死的……你一定要给我爹报仇",32);
//	PlayerGoto(22,28);
//	SetPlayerDir(5);
//	Say("杨影枫：紫轩……等着我……",7);
//	Say("紫轩：嗯……杨大哥",20);
	PlayerGoto(20,29);
	SetPlayerDir(5);
	Sleep(1000);
	Say("杨影枫：（充满信心）……",2);
	PlayerRunTo(10,48);
	SetPlayerDir(1);
	Say("杨影枫：纳兰潜凛，今日之战无论胜败，只是你我二人之事，以后不准你再为难我身后的人",6);
	Say("纳兰潜凛：哼……几个弱质女子根本不在老夫眼里。",39);
	Say("杨影枫：好，那我们开始吧！",6);
	Say("纳兰潜凛：看招……",39);

	SetNpcRelation("纳兰真",2);
	SetNpcRelation("月眉儿",2);
	SetNpcRelation("蔷薇",2);
//	SetNpcRelation("紫轩",2);
	SetNpcRelation("纳兰潜凛",1);

	SetNpcDeathScript("纳兰潜凛","纳兰潜凛死亡.txt");
	EnableNpcAI();
	Assign($Event, 2041);
	Return;

